corrected_code:
package graph

import (
	"context"
	"errors"
	"myapp/auth"
	"myapp/graph/model"
)

type QueryResolver struct {
	*Resolver
}

func (r *QueryResolver) BankTransfer(ctx context.Context, id string) (*model.BankTransfer, error) {
	currentUser, ok := auth.UserFromContext(ctx)
	if !ok {
		return nil, errors.New("unauthenticated")
	}

	transfer, err := r.TransferRepo.FindByID(ctx, id)
	if err != nil {
		return nil, err
	}

	if transfer.OwnerUserID != currentUser.ID {
		return nil, errors.New("forbidden: transfer belongs to another account")
	}

	return transfer, nil
}
